package pe.airepredict;

import android.Manifest;
import android.app.Activity;
import android.appwidget.AppWidgetManager;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.view.View;
import android.webkit.*;
import android.widget.*;
import org.json.*;

public class MainActivity extends Activity {
    private final int INK=Color.rgb(18,63,60),MUTED=Color.rgb(102,122,115),PAPER=Color.rgb(246,247,242),ACCENT=Color.rgb(218,234,177);
    private FrameLayout content;private TextView status,value,date,measured,modelInfo;private WebView web;
    private String page="";private int generation=0;private boolean historical=false;private JSONObject displayed=new JSONObject();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable freshnessCheck=new Runnable(){public void run(){if(page.equals("stations")&&!historical&&value!=null&&!ForecastData.fresh(displayed)){value.setText("— µg/m³");date.setText("Sin predicción actual vigente");}handler.postDelayed(this,60000);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(PAPER);getWindow().setNavigationBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(PAPER);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(0,insets.getSystemWindowInsetTop(),0,insets.getSystemWindowInsetBottom());return insets;});setContentView(root);
        LinearLayout header=new LinearLayout(this);header.setGravity(android.view.Gravity.CENTER_VERTICAL);header.setPadding(dp(22),dp(17),dp(22),dp(12));ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.app_icon);header.addView(icon,new LinearLayout.LayoutParams(dp(38),dp(38)));TextView title=text("AirePredict",23,INK);title.setPadding(dp(10),0,0,0);header.addView(title);root.addView(header);
        content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setPadding(dp(8),dp(8),dp(8),dp(10));for(String label:new String[]{"Inicio","Mapa","Estaciones","Ajustes"}){Button b=new Button(this);b.setText(label);b.setTextSize(10);b.setAllCaps(false);b.setTextColor(INK);b.setBackgroundColor(PAPER);nav.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));b.setOnClickListener(v->{if(label.equals("Inicio"))home();else if(label.equals("Mapa"))map();else if(label.equals("Estaciones"))stations();else settings();});}root.addView(nav);ForecastJob.schedule(this);int requested=getIntent().getIntExtra("station_id",-1);String site=getIntent().getStringExtra("site_id");boolean known=false;for(int id:ForecastData.IDS)if(id==requested)known=true;if(known){ForecastData.preferences(this).edit().putInt("station_id",requested).apply();stations();}else if(site!=null&&site.matches("[a-f0-9]{12}"))map();else home();
    }
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private TextView text(String value,int size,int color){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(color);view.setLineSpacing(dp(3),1);return view;}
    private GradientDrawable background(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(14));return d;}
    private LinearLayout screen(String name){page=name;generation++;content.removeAllViews();if(web!=null){web.destroy();web=null;}ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(23),dp(16),dp(23),dp(25));scroll.addView(box);content.addView(scroll);return box;}
    private void gap(LinearLayout box,int height){box.addView(new View(this),new LinearLayout.LayoutParams(1,dp(height)));}
    private LinearLayout card(LinearLayout box,int color){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(21),dp(22),dp(21),dp(22));card.setBackground(background(color));box.addView(card,new LinearLayout.LayoutParams(-1,-2));gap(box,15);return card;}
    private void heading(LinearLayout box,String kicker,String title,String description){box.addView(text(kicker,10,MUTED));gap(box,14);box.addView(text(title,34,INK));gap(box,12);box.addView(text(description,13,MUTED));gap(box,24);}
    private Button button(LinearLayout box,String label,Runnable action){Button b=AppButtons.create(this,label,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(7));box.addView(b,p);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setOnClickListener(v->action.run());return b;}
    private void home(){LinearLayout box=screen("home");heading(box,"INTELIGENCIA AMBIENTAL · PERÚ","El aire,\nen perspectiva.","Descubre patrones del aire con un mapa histórico y modelos por distrito. Datos, antes que suposiciones.");button(box,"Explorar mapa y modelo general  ↗",this::map);button(box,"Consultar mi distrito  →",this::stations);button(box,"Puno · calidad del aire",()->startActivity(new Intent(this,PunoActivity.class)));button(box,"Usar mi ubicación",()->startActivity(new Intent(this,NearbyActivity.class)));gap(box,21);
        LinearLayout general=card(box,Color.WHITE);general.addView(text("01 / MODELO GENERAL",10,MUTED));gap(general,10);general.addView(text("El contexto del territorio",21,INK));TextView summary=text("Conectando con el servicio… El primer inicio puede tardar un minuto.",12,MUTED);general.addView(summary);int token=generation;
        new Thread(()->{try{JSONObject report=ForecastData.request(this,"/api/atlas").getJSONObject("general_model");String message=report.getJSONObject("counts").getInt("scanned_rows")+" registros revisados\n"+report.getInt("training_sites")+" puntos en el entrenamiento\nMAE de prueba: "+String.format(java.util.Locale.US,"%.2f",report.getJSONObject("test").getDouble("mae"))+" µg/m³\n\nPredicción diaria histórica. No es una medición actual.";runOnUiThread(()->{if(generation==token)summary.setText(message);});}catch(Exception e){runOnUiThread(()->{if(generation==token)summary.setText("No se pudo conectar todavía. Comprueba la conexión en Ajustes y vuelve a intentarlo.");});}}).start();
        LinearLayout local=card(box,INK);local.addView(text("02 / MODELOS POR ESTACIÓN",10,ACCENT));gap(local,10);local.addView(text("Una mirada más cercana",21,Color.WHITE));gap(local,10);local.addView(text("Jesús María · San Borja · San Martín de Porres\n\nPredicciones de una hora con datos recientes. Cada punto conserva su propia evaluación y versiones de respaldo.",12,Color.rgb(192,209,197)));button(box,"Configurar widget y notificaciones",this::settings);box.addView(text("Experimental. La concentración de PM2.5 no equivale a un índice oficial ni a una recomendación de salud.",11,MUTED));}
    @android.annotation.SuppressLint("SetJavaScriptEnabled") private void map(){LinearLayout box=screen("map");heading(box,"EXPLORACIÓN GEOGRÁFICA","El territorio, en datos.","Selecciona un punto, filtra por departamento y explora su histórico. El modelo general tiene un horizonte diario.");button(box,"Usar mi ubicación",()->startActivity(new Intent(this,NearbyActivity.class)));TextView connection=text("Cargando mapa… El servidor gratuito puede tardar un minuto en iniciarse.",11,MUTED);box.addView(connection);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setBackgroundColor(PAPER);
        web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri uri=request.getUrl(),origin=Uri.parse(ForecastData.baseUrl(MainActivity.this));if("https".equals(uri.getScheme())&&origin.getHost().equals(uri.getHost())&&origin.getPort()==uri.getPort())return false;if("https".equals(uri.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,uri));return true;}@Override public void onPageFinished(WebView view,String url){connection.setText("Mapa histórico · consulta la fecha de cada observación.");}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())connection.setText("No se pudo cargar el mapa. Comprueba la conexión en Ajustes.");}});box.addView(web,new LinearLayout.LayoutParams(-1,dp(940)));String site=getIntent().getStringExtra("site_id");web.loadUrl(ForecastData.baseUrl(this)+"/?embedded=1"+(site!=null&&site.matches("[a-f0-9]{12}")?"&site="+Uri.encode(site):"")+"#explorar");}
    private void stations(){LinearLayout box=screen("stations");heading(box,"MODELOS POR ESTACIÓN","Tu distrito,\ncon contexto.","Cada predicción usa el modelo y el sensor del distrito seleccionado.");Spinner select=new Spinner(this);select.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ForecastData.NAMES));int current=0;for(int i=0;i<ForecastData.IDS.length;i++)if(ForecastData.IDS[i]==ForecastData.stationId(this))current=i;select.setSelection(current);box.addView(select);select.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){int next=ForecastData.IDS[position];if(next!=ForecastData.stationId(MainActivity.this)){ForecastData.preferences(MainActivity.this).edit().putInt("station_id",next).apply();ForecastWidget.refreshAll(MainActivity.this);refresh(false);}}});
        button(box,"Actualizar datos actuales  ↻",()->refresh(false));button(box,"Explorar predicción histórica",()->refresh(true));gap(box,12);LinearLayout forecast=card(box,INK);forecast.addView(text("ESTIMACIÓN DE LA PRÓXIMA HORA",10,ACCENT));value=text("— µg/m³",38,Color.WHITE);forecast.addView(value);date=text("Sin predicción cargada",12,Color.rgb(192,209,197));forecast.addView(date);status=text("",12,MUTED);box.addView(status);gap(box,15);LinearLayout readings=card(box,Color.WHITE);readings.addView(text("ÚLTIMA MEDICIÓN RECIBIDA",10,MUTED));measured=text("Consultando…",15,INK);readings.addView(measured);modelInfo=text("Evaluación histórica: cargando…",11,MUTED);box.addView(modelInfo);gap(box,15);box.addView(text("Actualizar consulta el servidor; no adelanta la publicación del proveedor. Una medición retrasada puede estar disponible aunque no haya una predicción actual.",11,MUTED));refresh(false);}
    private void render(JSONObject data){displayed=data;boolean recorded=data.optString("mode").equals("historical"),fresh=ForecastData.fresh(data);historical=recorded;value.setText(recorded||fresh?ForecastData.value(data):"— µg/m³");date.setText(recorded?"Histórico · "+ForecastData.time(data):fresh?ForecastData.time(data):"Sin predicción actual vigente");status.setText(recorded?"Ejemplo histórico: no describe las condiciones actuales.":fresh?"Conectado · predicción actual experimental":"Conectado · no hay datos recientes para predecir.");if(data.has("last_observation_utc"))measured.setText(String.format(java.util.Locale.US,"%.2f µg/m³\n",data.optDouble("last_observed_pm25"))+ForecastData.formatTime(data.optString("last_observation_utc")));}
    private void refresh(boolean recorded){if(!page.equals("stations"))return;final int token=++generation,id=ForecastData.stationId(this);historical=recorded;displayed=new JSONObject();value.setText("— µg/m³");date.setText("Consultando el servicio…");measured.setText("Consultando mediciones…");status.setText("Conectando… El primer inicio puede tardar un minuto.");new Thread(()->{try{JSONObject data=ForecastData.fetchStation(this,id,recorded);runOnUiThread(()->{if(generation==token&&page.equals("stations"))render(data);});ForecastWidget.refreshAll(this);}catch(Exception e){String message=e.getMessage();runOnUiThread(()->{if(generation==token){value.setText("— µg/m³");date.setText(recorded?"Histórico no disponible":"Predicción actual no disponible");status.setText(message);}});if(!recorded)try{JSONArray rows=ForecastData.request(this,"/api/stations/"+id+"/observations").getJSONArray("history");String info=rows.length()==0?"El servicio responde, pero aún no hay mediciones publicadas.":String.format(java.util.Locale.US,"%.2f µg/m³\n",rows.getJSONObject(rows.length()-1).getDouble("pm25"))+ForecastData.formatTime(rows.getJSONObject(rows.length()-1).getString("timestamp"));runOnUiThread(()->{if(generation==token)measured.setText(info);});}catch(Exception ignored){runOnUiThread(()->{if(generation==token)measured.setText("No se pudo consultar la medición. Comprueba la conexión en Ajustes.");});}}
        try{JSONArray stations=ForecastData.request(this,"/api/stations").getJSONArray("stations");for(int i=0;i<stations.length();i++){JSONObject s=stations.getJSONObject(i);if(s.getInt("id")==id){JSONObject metric=s.getJSONObject("metrics").getJSONObject("combinado").getJSONObject("test");String note="Prueba histórica: MAE "+String.format(java.util.Locale.US,"%.2f",metric.getDouble("mae"))+" µg/m³ · R² "+String.format(java.util.Locale.US,"%.3f",metric.getDouble("r2"))+"\nMLOps independiente · promoción condicionada a métricas";runOnUiThread(()->{if(generation==token)modelInfo.setText(note);});}}}catch(Exception ignored){}}).start();}
    private void settings(){LinearLayout box=screen("settings");heading(box,"CONEXIÓN Y PREFERENCIAS","A tu manera.","Conecta el servicio y elige cómo consultar las predicciones.");box.addView(text("Servidor de la aplicación",12,MUTED));EditText origin=new EditText(this);origin.setText(ForecastData.baseUrl(this));origin.setSingleLine(true);origin.setTextSize(12);origin.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);box.addView(origin);TextView result=text("",12,MUTED);box.addView(result);
        button(box,"Guardar y comprobar conexión",()->{try{String url=ForecastData.validateUrl(origin.getText().toString());android.content.SharedPreferences.Editor edit=ForecastData.preferences(this).edit().putString("base_url",url);for(String key:ForecastData.preferences(this).getAll().keySet())if(key.startsWith("forecast"))edit.remove(key);edit.apply();result.setText("Comprobando… Puede tardar un minuto si el servidor está suspendido.");int token=generation;new Thread(()->{try{ForecastData.request(this,"/health");runOnUiThread(()->{if(generation==token)result.setText("Conexión correcta. Ya puedes consultar mapa y estaciones.");});}catch(Exception e){runOnUiThread(()->{if(generation==token)result.setText("No se pudo conectar. Revisa la dirección HTTPS e inténtalo de nuevo.");});}}).start();}catch(Exception e){result.setText(e.getMessage());}});
        gap(box,20);box.addView(text("Tu pantalla de inicio",23,INK));button(box,"Añadir widget a la pantalla de inicio",()->{AppWidgetManager manager=getSystemService(AppWidgetManager.class);if(manager.isRequestPinAppWidgetSupported()){manager.requestPinAppWidget(new ComponentName(this,ForecastWidget.class),null,null);result.setText("Confirma la solicitud en tu pantalla de inicio. El widget usará "+ForecastData.stationName(this)+".");}else result.setText("Mantén pulsada la pantalla de inicio y selecciona Widgets → AirePredict.");});
        button(box,"Activar notificaciones de predicción",()->{ForecastData.preferences(this).edit().putBoolean("notifications",true).apply();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},100);else result.setText("Notificaciones activadas para predicciones recientes.");});button(box,"Desactivar notificaciones",()->{ForecastData.preferences(this).edit().putBoolean("notifications",false).apply();result.setText("Notificaciones desactivadas.");});gap(box,13);box.addView(text("La ubicación aproximada es opcional y solo se solicita al pulsar «Usar mi ubicación». Puedes usar la aplicación sin aceptar ubicación ni notificaciones. Android decide cuándo actualizar el widget.",11,MUTED));}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==100){boolean granted=results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED;ForecastData.preferences(this).edit().putBoolean("notifications",granted).apply();Toast.makeText(this,granted?"Notificaciones activadas.":"Notificaciones rechazadas. La aplicación y el widget siguen disponibles.",Toast.LENGTH_LONG).show();}}
    @Override protected void onResume(){super.onResume();handler.post(freshnessCheck);}
    @Override protected void onPause(){handler.removeCallbacks(freshnessCheck);super.onPause();}
    @Override protected void onDestroy(){if(web!=null)web.destroy();super.onDestroy();}
}
